'use strict';
let adminCSRF=null,adminData=null,adminBusy=false;
const ael=s=>document.querySelector(s),aesc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),usd=n=>new Intl.NumberFormat('az',{style:'currency',currency:'USD'}).format(Number(n)/1000000);
function adminMessage(s,error=false){ael('#message').textContent=s;ael('#message').className=error?'error':''}
async function adminAPI(url,data){const r=await fetch(url,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json',...(adminCSRF?{'X-CSRF-Token':adminCSRF}:{})},...(data===undefined?{}:{body:JSON.stringify(data)})});if(!r.ok){let e;try{e=(await r.json()).error}catch{}throw Error(e||'Sorğu tamamlanmadı')}return r.json()}
function adminTable(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th>${aesc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||'<tr><td>Təsdiqlənmiş qeyd yoxdur.</td></tr>'}</tbody></table>`}
function paintAdmin(){const d=adminData,f=d.fund,t=d.totals;ael('#login').hidden=true;ael('#dashboard').hidden=false;ael('#logout').hidden=false;ael('#notices').innerHTML=d.notices.map(n=>`<p class="admin-notice">${aesc(n.message)} <small>${aesc(n.created)}</small></p>`).join('');const metrics=[['Satış sayı (təsdiqlənmiş maliyyə)',t.reconciled],['Brüt (məlum)',usd(t.gross)],['Faktiki komissiya (məlum)',usd(t.fee)],['Vergilər (məlum)',usd(t.tax)],['Digər tutulmalar (məlum)',usd(t.other)],['Xalis gəlir',usd(t.net)],['Xeyriyyəyə ayrılmış',usd(f.collected)],['Fond balansı',usd(f.balance)],['Paylanmış',usd(f.distributed)]];ael('#metrics').innerHTML=metrics.map(([label,value])=>`<div><small>${label}</small><b>${aesc(value)}</b></div>`).join('')+(t.netOnly?`<p>${t.netOnly} qeyd artıq-xalis üsulundadır; onların brüt/komissiya bölgüsü məlum toplamlarına daxil deyil.</p>`:'');ael('#orders').innerHTML=adminTable(['Google order','Status','Brüt','Komissiya','Xalis','Xeyriyyə','Sübut'],d.orders.map(o=>`<tr><td>${aesc(o.id)}</td><td>${o.is_test?'TEST — fonda daxil deyil':o.blocked?'Refund — uzlaşdırılmalıdır':o.revision?'Təsdiqlənib · v'+o.revision:'Faktiki maliyyə gözlənilir'}</td><td>${o.gross===null?'—':usd(o.gross)}</td><td>${o.fee===null?'—':usd(o.fee)}</td><td>${o.net===null?'—':usd(o.net)}</td><td>${o.blocked?'—':o.charity===null?'—':usd(o.charity)}</td><td>${o.document_id?`<a href="/api/admin/documents/${aesc(o.document_id)}" target="_blank" rel="noopener">Sənəd</a>`:'—'}</td></tr>`));const selectedOrder=ael('#settlementForm select[name=order]').value;ael('#settlementForm select[name=order]').innerHTML='<option value="">Order seçin</option>'+d.orders.filter(o=>!o.is_test).map(o=>`<option value="${aesc(o.id)}">${aesc(o.id)} · v${o.revision||0}</option>`).join('');ael('#settlementForm select[name=order]').value=selectedOrder;ael('#drafts').innerHTML=d.drafts.map(x=>`<article class="card"><strong>${aesc(x.organization)} · ${usd(x.amount)}</strong><p>${aesc(x.date)}</p><a href="/api/admin/documents/${aesc(x.document_id)}" target="_blank" rel="noopener">İctimai olacaq sübutu yoxla</a><p><button class="goldbtn" data-confirm-distribution="${aesc(x.id)}">Ödəniş edilib — manual təsdiqlə</button></p></article>`).join('');ael('#history').innerHTML=f.distributions.map(x=>`<p>${aesc(x.date)} · ${aesc(x.organization)} · <b>${usd(x.amount)}</b> · <a href="${aesc(x.document)}" target="_blank" rel="noopener">Sübut</a></p>`).join('')||'Hələ paylanma yoxdur.';ael('#audit').innerHTML=adminTable(['Tarix','İcraçı','Əməl','İstinad','Hash'],d.audit.map(x=>`<tr><td>${aesc(x.created)}</td><td>${aesc(x.actor)}</td><td>${aesc(x.action)}</td><td>${aesc(x.reference)}</td><td><code>${aesc(x.hash)}</code></td></tr>`));}
async function refreshAdmin(){try{adminData=await adminAPI('/api/admin/overview');adminCSRF=adminData.csrf;paintAdmin()}catch(e){adminMessage(adminCSRF?e.message:'Davam etmək üçün admin girişi edin.',!!adminCSRF)}}
async function uploadEvidence(file){if(!file||file.size>5*1024*1024)throw Error('PDF/PNG/JPEG, maksimum 5 MB seçin');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});return adminAPI('/api/admin/documents',{mime:file.type,data})}
async function adminAction(fn){if(adminBusy)return;adminBusy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();adminMessage('Təsdiqləndi.');await refreshAdmin()}catch(e){adminMessage(e.message,true)}finally{adminBusy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false)}}
ael('#loginForm').addEventListener('submit',async e=>{e.preventDefault();await adminAction(async()=>{const s=await adminAPI('/api/admin/login',{password:e.target.elements.password.value});adminCSRF=s.csrf;e.target.reset()})});
ael('#refresh').addEventListener('click',refreshAdmin);ael('#reconcile').addEventListener('click',()=>adminAction(()=>adminAPI('/api/admin/reconcile',{})));
ael('#logout').addEventListener('click',async()=>{try{await adminAPI('/api/admin/logout',{})}finally{adminCSRF=null;adminData=null;ael('#dashboard').hidden=true;ael('#login').hidden=false;ael('#logout').hidden=true;adminMessage('Çıxış edildi.')}});
ael('#settlementForm select[name=mode]').addEventListener('change',e=>{const gross=e.target.value==='gross';ael('#grossFields').hidden=!gross;ael('#netField').hidden=gross;for(const input of ael('#grossFields').querySelectorAll('input')){input.disabled=!gross;input.required=gross}ael('#netField input').disabled=gross;ael('#netField input').required=!gross});
ael('#settlementForm').addEventListener('submit',e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f)),order=adminData.orders.find(o=>o.id===values.order);if(!order)return adminMessage('Order seçin',true);const revision=order.revision||0;adminAction(async()=>{const doc=await uploadEvidence(f.elements.evidence.files[0]),payload={order:values.order,mode:values.mode,revision,reference:values.reference,document:doc.id};for(const key of values.mode==='gross'?['gross','fee','tax','other']:['net'])payload[key]=values[key];await adminAPI('/api/admin/settlements',payload);f.reset()})});
ael('#distributionForm').addEventListener('submit',e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));adminAction(async()=>{const doc=await uploadEvidence(f.elements.evidence.files[0]);await adminAPI('/api/admin/distributions',{organization:v.organization,amount:v.amount,date:v.date,document:doc.id});f.reset()})});
ael('#drafts').addEventListener('click',e=>{const button=e.target.closest('[data-confirm-distribution]');if(!button)return;const d=adminData.drafts.find(x=>x.id===button.dataset.confirmDistribution);if(!d)return;if(window.confirm(`${d.organization}: ${usd(d.amount)} real olaraq ödənilib? Sənəd ictimai görünəcək və məbləğ balansdan çıxılacaq.`))adminAction(()=>adminAPI('/api/admin/distributions/confirm',{id:d.id,confirmed:true}))});
refreshAdmin();setInterval(()=>{if(adminCSRF&&!adminBusy)refreshAdmin()},60000);
